import{_ as r,o as e,c as i,b6 as a,bT as o,bU as l,bV as n,bW as s,bX as g,bY as d,bZ as b,b_ as p,b$ as h,c0 as c,c1 as u,c2 as m,c3 as _,c4 as f,c5 as k,c6 as A,c7 as q,c8 as P,c9 as I,ca as x,cb as C,cc as v,cd as V,ce as W,cf as w,cg as S,ch as D,ci as T,cj as U,ck as M,cl as y,cm as L,cn as R,co as E,cp as G}from"./chunks/framework.BUXTSoD9.js";const F=JSON.parse('{"title":"مقارنة بين سبع أدوات برمجة بالذكاء الاصطناعي","description":"","frontmatter":{},"headers":[],"relativePath":"ar-sa/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.md","filePath":"ar-sa/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.md"}'),X={name:"ar-sa/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.md"};function Z(z,t,N,O,$,H){return e(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="مقارنة-بين-سبع-أدوات-برمجة-بالذكاء-الاصطناعي" tabindex="-1">مقارنة بين سبع أدوات برمجة بالذكاء الاصطناعي <a class="header-anchor" href="#مقارنة-بين-سبع-أدوات-برمجة-بالذكاء-الاصطناعي" aria-label="Permalink to “مقارنة بين سبع أدوات برمجة بالذكاء الاصطناعي”">​</a></h1><h2 id="مقدمة-الفصل" tabindex="-1">مقدمة الفصل <a class="header-anchor" href="#مقدمة-الفصل" aria-label="Permalink to “مقدمة الفصل”">​</a></h2><p>أمام هذا الكم الهائل من أدوات البرمجة بالذكاء الاصطناعي، أيُّها الأنسب لك؟ في هذا الفصل، نُجري تقييمًا أفقيًا معمّقًا لسبع منصات Vibe Coding على الويب — منها Lovable و Replit و Z.ai — من خلال مهمة عملية موحدة: تطوير لعبة &quot;الثعبان + كتابة القصائد بالذكاء الاصطناعي&quot;. سنقارنها من عدة أبعاد مثل سهولة الاستخدام للمبتدئين، والتحكم في الكود، وسهولة النشر، لمساعدتك على اختيار أقوى أداة مساعدة في التطوير.</p><hr><h1 id="_1-بناء-لعبة-الثعبان-باستخدام-vibe-coding-دراسة-تعليمية-كاملة" tabindex="-1">1. بناء لعبة الثعبان باستخدام Vibe Coding: دراسة تعليمية كاملة <a class="header-anchor" href="#_1-بناء-لعبة-الثعبان-باستخدام-vibe-coding-دراسة-تعليمية-كاملة" aria-label="Permalink to “1. بناء لعبة الثعبان باستخدام Vibe Coding: دراسة تعليمية كاملة”">​</a></h1><p>تقدم هذه المقالة ممارسة تطوير برمجية جديدة تُسمّى &quot;Vibe Coding&quot;، والتي تستفيد من الذكاء الاصطناعي لتسريع عملية بناء التطبيقات.</p><p>بعد ذلك، سنقدم بالتتابع المفاهيم الأساسية لـ Vibe Coding، ونشرح ما هو AI Agent، ونقدم أساليب عملية لكتابة الأوامر التوجيهية (Prompts). أخيرًا، سنبني من الصفر لعبة &quot;الثعبان (Snake)&quot; كتطبيق عملي كامل، مع مقارنة وتقييم مفصّل لعدة منصات Vibe Coding رئيسية، لمساعدتك على اختيار مجموعة الأدوات الأنسب لك.</p><h2 id="ما-ستتعلمه" tabindex="-1">ما ستتعلمه: <a class="header-anchor" href="#ما-ستتعلمه" aria-label="Permalink to “ما ستتعلمه:”">​</a></h2><ul><li><strong>ما هو Vibe Coding:</strong> تعرّف على تعريفه، وسير عمله، ومزاياه الرئيسية.</li><li><strong>دور AI Agent:</strong> افهم طريقة عمل AI Agent والفرق بينه وبين البرامج التقليدية.</li><li><strong>كيفية كتابة أوامر توجيهية جيدة:</strong> أتقن كتابة أوامر واضحة ومحددة للحصول على نتائج أفضل.</li><li><strong>أدوات Vibe Coding:</strong> تعرّف على مجموعة من منصات البرمجة والتصميم بالذكاء الاصطناعي.</li><li><strong>مقارنة المنصات:</strong> قيّم وقارن بين مزايا وعيوب 7 منصات AI Agent مختلفة من منظور المبتدئين.</li><li><strong>أدوات UI / UX:</strong> تعلّم كيفية دمج أدوات UI/UX مثل Figma و Mastergo في سير العمل الشامل.</li></ul><h2 id="_1-مقدمة" tabindex="-1">1. مقدمة <a class="header-anchor" href="#_1-مقدمة" aria-label="Permalink to “1. مقدمة”">​</a></h2><p>في الدروس السابقة، كنا نستخدم نموذج التطوير الشامل من z.ai لإنجاز مهام البرمجة.</p><p>لكن هل فكّرنا يومًا: جوهره هو في الواقع &quot;AI Agent&quot; (يختلف عن الذكاء الاصطناعي التفاعلي العادي، وهو أكثر ذكاءً بكثير)؟ فهو لا يقتصر على التحدث معك، بل يستطيع التفكير (عندما تعطيه مهمة، يضع خطة أولاً)، ويتخذ إجراءات بشكل استباقي (مثل الاتصال بالبحث على الويب، وتنفيذ أوامر الكمبيوتر، وفتح صفحات الويب وغيرها من الأدوات). سنتحدث عن هذا بالتفصيل لاحقًا.</p><h2 id="_1-ما-هو-vibe-coding؟" tabindex="-1">1. ما هو Vibe Coding؟ <a class="header-anchor" href="#_1-ما-هو-vibe-coding؟" aria-label="Permalink to “1. ما هو Vibe Coding؟”">​</a></h2><p>Vibe Coding هو أسلوب جديد في تطوير البرمجيات يستفيد من الذكاء الاصطناعي لتسريع عملية تطوير التطبيقات. إنه ليس بديلاً عن البرمجة التقليدية، بل هو نمط برمجة أكثر &quot;تحاوريًا&quot;. ابتكر هذا المفهوم باحث الذكاء الاصطناعي Andrej Karpathy: في سير العمل هذا، لم يعد المطور يكتب الكود سطرًا بسطر، بل يوجّه AI Agent بشكل أساسي لتوليد التطبيقات وتحسينها وتصحيح أخطائها.</p><p>الفكرة الأساسية في Vibe Coding هي التحول من <strong>&quot;التركيز على الكود (code-first)&quot;</strong> إلى <strong>&quot;التركيز على النية (intent-first)&quot;</strong>. لم تعد بحاجة للبدء بالتفكير من أول سطر كود، بل تصف ما تريده باللغة الطبيعية.</p><p>سير العمل النموذجي لـ Vibe Coding هو حلقة تكرارية مستمرة:</p><ul><li><strong>وصف الهدف:</strong> صِف الميزة التي تريد تنفيذها بجملة أو فقرة، مثل: &quot;اصنع لعبة ثعبان بسيطة مع خلفية Python يمكنها توليد القصائد.&quot;</li><li><strong>توليد الكود بالذكاء الاصطناعي:</strong> يحلل AI Agent متطلباتك ويولّد النسخة الأولى من الكود، بما في ذلك الهيكل الأساسي وصفحة الواجهة الأمامية ومنطق الواجهة الخلفية.</li><li><strong>التشغيل والملاحظة:</strong> شغّل الكود المُولَّد، وتحقق مما إذا كان يعمل كما هو متوقع، واكتشف الأخطاء أو أوجه القصور.</li><li><strong>التكرار والتحسين:</strong> إذا كانت هناك أخطاء أو النتائج غير مُرضية، استمر في إعطاء التعليمات في المحادثة، مثل: &quot;الثعبان يتحرك ببطء شديد، زيّد السرعة&quot;، أو &quot;ملف <code>.env</code> لا يقرأ مفتاح API بشكل صحيح، أصلح كود الواجهة الخلفية.&quot;</li><li><strong>كرر الخطوات أعلاه:</strong> استمر في التكرار ضمن حلقة &quot;وصف ← توليد ← تشغيل ← تحسين&quot; حتى يصل التطبيق إلى حالة مُرضية.</li></ul><h3 id="المزايا-الرئيسية-لـ-vibe-coding" tabindex="-1">المزايا الرئيسية لـ Vibe Coding: <a class="header-anchor" href="#المزايا-الرئيسية-لـ-vibe-coding" aria-label="Permalink to “المزايا الرئيسية لـ Vibe Coding:”">​</a></h3><ul><li><strong>خفض الحاجز:</strong> يتيح للمصممين ورواد الأعمال والطلاب الذين يفتقرون إلى خبرة البرمجة المشاركة في تطوير التطبيقات عبر اللغة الطبيعية.</li><li><strong>النماذج الأولية السريعة:</strong> يُقلّص الوقت من الفكرة إلى الحد الأدنى من المنتج القابل للتطبيق (MVP) بشكل كبير.</li><li><strong>رفع الكفاءة:</strong> يعالج تلقائيًا الكثير من أعمال الترميز المتكررة والآلية (مثل الكود النموذجي)، مما يتيح للمطورين التركيز على التصميم المعماري وتجريد المشكلات.</li><li><strong>تسهيل التجريب:</strong> يشجع على الإنتاج السريع أولاً ثم التحسين المستمر، مما يجعل تجربة الأفكار والميزات الجديدة أسهل.</li></ul><h2 id="_2-ما-هي-منصات-vibe-coding-عبر-الويب-web-based-؟" tabindex="-1">2. ما هي منصات Vibe Coding عبر الويب (Web-based)؟ <a class="header-anchor" href="#_2-ما-هي-منصات-vibe-coding-عبر-الويب-web-based-؟" aria-label="Permalink to “2. ما هي منصات Vibe Coding عبر الويب (Web-based)؟”">​</a></h2><p>في هذا الاختبار العملي، ستلاحظ أن الأدوات التي نقيمها مقسمة إلى فئتين: <strong>Web-based (منصات عبر الويب)</strong> و <strong>IDE (بيئات تطوير محلية)</strong>.</p><p>رغم أن جوهرها جميعًا هو استخدام الذكاء الاصطناعي لكتابة الكود، إلا أن هناك اختلافات كبيرة في تجربة الاستخدام والسيناريوهات المطبقة:</p><h3 id="منصات-vibe-coding-عبر-الويب-web-based" tabindex="-1">منصات Vibe Coding عبر الويب (Web-based) <a class="header-anchor" href="#منصات-vibe-coding-عبر-الويب-web-based" aria-label="Permalink to “منصات Vibe Coding عبر الويب (Web-based)”">​</a></h3><p><strong>الأدوات الممثلة:</strong> Lovable، Replit، Z.ai، v0</p><p>هذا مثل &quot;شقة فندقية جاهزة للسكن&quot;.</p><ul><li><strong>لا حاجة لإعداد البيئة:</strong> لا تحتاج للقلق بشأن بيئة Python أو إصدار Node.js، ولا حول تثبيت التبعيات. افتح المتصفح، أدخل العنوان، وابدأ بكتابة الكود مباشرة.</li><li><strong>معاينة ونشر بنقرة واحدة:</strong> بعد توليد الكود، تعرض المنصة عادةً النتيجة تلقائيًا في نافذة جانبية. وعند الانتهاء، اضغط على زر للحصول على رابط لمشاركته مع أصدقائك.</li><li><strong>السيناريوهات المناسبة:</strong><ul><li><strong>التحقق السريع من الأفكار (MVP):</strong> لديك فكرة في ذهنك وتريد قضاء نصف ساعة لترى إن كان يمكنك تنفيذها.</li><li><strong>للمبتدئين:</strong> لا تريد أن تُحبط بسبب أخطاء البيئة المعقدة، وتريد فقط تجربة متعة البرمجة بالذكاء الاصطناعي.</li><li><strong>التطبيقات الخفيفة:</strong> صنع صفحة أداة بسيطة أو لعبة صغيرة أو صفحة عرض شخصية.</li></ul></li></ul><h3 id="ai-ide-بيئة-التطوير-المحلية" tabindex="-1">AI IDE (بيئة التطوير المحلية) <a class="header-anchor" href="#ai-ide-بيئة-التطوير-المحلية" aria-label="Permalink to “AI IDE (بيئة التطوير المحلية)”">​</a></h3><p><strong>الأدوات الممثلة:</strong> Cursor، Trae، VS Code + إضافات AI</p><p>هذا مثل &quot;منزل مملوك مُشطَّب بالكامل&quot;.</p><ul><li><strong>قدرات محلية قوية:</strong> يعمل على كمبيوترك، ويمكنه الوصول مباشرة إلى جميع ملفاتك المحلية والاستفادة من قوة المعالجة في جهازك.</li><li><strong>تكامل سلس مع سير العمل المهني:</strong> مناسب للمشاريع الكبيرة، حيث يمكنك تثبيت مكونات إضافية متنوعة بحرية، والاتصال بقواعد البيانات المحلية، وإجراء تصحيح الأخطاء المعقد.</li><li><strong>السيناريوهات المناسبة:</strong><ul><li><strong>تطوير المشاريع المهنية:</strong> المشاريع التجارية التي تتطلب صيانة طويلة الأمد وهيكلًا معقدًا.</li><li><strong>التخصيص العميق:</strong> تحتاج إلى تحكم دقيق في تفاصيل الكود، أو تحتاج إلى تكامل عميق مع سير العمل المحلي (مثل Git و Docker).</li><li><strong>خصوصية البيانات:</strong> الكود بالكامل محليًا، مما يتوافق بشكل أكبر مع معايير الأمان لبعض المؤسسات.</li></ul></li></ul><p><strong>باختصار:</strong> إذا كنت قد بدأت للتو في البرمجة بالذكاء الاصطناعي، أو تريد فقط صنع شيء صغير بسرعة، فإن <strong>المنصات عبر الويب</strong> هي نقطة بداية ممتازة. أما إذا كنت مطورًا محترفًا، أو أصبح مشروعك أكثر تعقيدًا، فإن <strong>بيئة التطوير المحلية (IDE)</strong> ستوفر لك إمكانيات أعلى.</p><hr><h2 id="_3-ما-هو-ai-agent؟" tabindex="-1">3. ما هو AI Agent؟ <a class="header-anchor" href="#_3-ما-هو-ai-agent؟" aria-label="Permalink to “3. ما هو AI Agent؟”">​</a></h2><h3 id="ما-هو-ai-agent؟" tabindex="-1">ما هو AI Agent؟ <a class="header-anchor" href="#ما-هو-ai-agent؟" aria-label="Permalink to “ما هو AI Agent؟”">​</a></h3><p>AI Agent هو نظام برمجي قادر على إدراك البيئة واتخاذ القرارات والتصرف بشكل مستقل لتحقيق أهداف محددة. مقارنة بالبرمجيات التقليدية التي تتبع تعليمات ثابتة وتدفقات عمل واحدة، فإن AI Agent أكثر مرونة وقدرة على التكيف.</p><p>فيما يلي بعض السمات الرئيسية التي تميز AI Agent عن البرامج التقليدية:</p><ul><li><strong>الاستقلالية (Autonomy):</strong> يتمتع AI Agent بمستوى عالٍ من الاستقلالية. البرامج التقليدية تتطلب عادةً أن يقوم الإنسان بتشغيلها خطوة بخطوة، بينما يمكن لـ Agent أن يقرر بشكل مستقل الخطوة التالية بناءً على الهدف.</li><li><strong>الإدراك والذاكرة (Perception &amp; Memory):</strong> يجمع Agent البيانات من البيئة (مثل استجابات API وبيانات المستشعرات ومُدخلات المستخدم)، ويحتفظ بالسياق من خلال &quot;الذاكرة&quot;، مما يتيح له إعادة استخدام الخبرات في الإجراءات اللاحقة والتحسين المستمر.</li><li><strong>العقلانية والتوجه نحو الهدف (Rationality &amp; Goal-Orientation):</strong> يحلل Agent ويخطط حول الهدف المحدد، ويختار تسلسل الإجراءات الأنسب لتحقيق &quot;مؤشرات أداء&quot; أعلى.</li><li><strong>استخدام الأدوات (Tool Use):</strong> من أبرز سمات AI Agent الحديثة قدرته على استدعاء أدوات خارجية، ولم يعد مقتصرًا على &quot;توليد النصوص&quot;. على سبيل المثال، يمكنه تصفح الويب، وتشغيل الكود، والاستعلام من قواعد البيانات، وإرسال البريد الإلكتروني، فهو &quot;عقل ينسق الأدوات&quot;.</li></ul><p>يمكن فهمه بهذا التشبيه:</p><ul><li><strong>البرنامج التقليدي</strong> مثل الآلة الحاسبة. تعطيه أرقامًا ومعاملات، وهو ينفذ الحساب فقط عند ضغطك على الزر.</li><li><strong>مساعد الذكاء الاصطناعي</strong> مثل المساعد البشري. تطلب منه &quot;ساعدني في العثور على مطاعم قريبة&quot;، فيبحث لك ويعرض الخيارات، لكن القرار النهائي يعود إليك.</li><li><strong>AI Agent</strong> أشبه بفريق بحثي آلي. تحتاج فقط إلى إعطائه هدفًا عامًا (مثل &quot;خطط لي رحلة إلى اليابان&quot;)، فيقوم بتفكيك المهام، والبحث على الإنترنت، وحجز الطيران والفنادق (عبر API)، وتنظيم الجدول، ويسلّمك النتيجة النهائية، كل ذلك تقريبًا دون الحاجة لتدخلك في التفاصيل.</li></ul><hr><h1 id="_2-حول-كتابة-الأوامر-التوجيهية-prompts" tabindex="-1">2. حول كتابة الأوامر التوجيهية (Prompts) <a class="header-anchor" href="#_2-حول-كتابة-الأوامر-التوجيهية-prompts" aria-label="Permalink to “2. حول كتابة الأوامر التوجيهية (Prompts)”">​</a></h1><h2 id="_1-هل-الأفضل-كتابة-أمر-توجيهي-واحد-كامل،-أم-تقسيمه-إلى-خطوات-متعددة؟" tabindex="-1">1. هل الأفضل كتابة أمر توجيهي واحد كامل، أم تقسيمه إلى خطوات متعددة؟ <a class="header-anchor" href="#_1-هل-الأفضل-كتابة-أمر-توجيهي-واحد-كامل،-أم-تقسيمه-إلى-خطوات-متعددة؟" aria-label="Permalink to “1. هل الأفضل كتابة أمر توجيهي واحد كامل، أم تقسيمه إلى خطوات متعددة؟”">​</a></h2><p>كثير من الناس يغريهم التفكير في كتابة &quot;تطبيق شامل كامل&quot; في أمر توجيهي واحد. في الواقع، الأدوات الحالية أصبحت قوية بما يكفي، ومن الممكن بالفعل الحصول على نتيجة تبدو جيدة من المحاولة الأولى. لكن من حيث التجربة الشاملة ومعدل النجاح، فإن تقسيم العمل إلى خطوات صغيرة والتكرار المرحلي غالبًا ما يعطي نتائج أفضل، ويقلل من خطر الدخول في &quot;طريق مسدود&quot; لا يمكن تعديله.</p><blockquote><p><strong>نصيحة صغيرة:</strong> بدلاً من توقع &quot;النتيجة المثالية من المحاولة الأولى&quot;، قسّم الهدف الكبير إلى مهام صغيرة قابلة للتنفيذ (To-do). على سبيل المثال، لا تقل مباشرة &quot;build me a Snake game&quot;، بل قسّمها إلى: &quot;1. اصنع أولاً واجهة أمامية للعبة الثعبان&quot;، &quot;2. ثم نفّذ واجهة خلفية لتسجيل النقاط&quot;، &quot;3. أخيرًا اربط الواجهتين الأمامية والخلفية&quot;. هذا يتيح للذكاء الاصطناعي فهم متطلباتك بدقة أكبر وإعطاء مخرجات أكثر موثوقية.</p></blockquote><h2 id="_2-كلما-كان-أوضح،-كان-أفضل" tabindex="-1">2. كلما كان أوضح، كان أفضل <a class="header-anchor" href="#_2-كلما-كان-أوضح،-كان-أفضل" aria-label="Permalink to “2. كلما كان أوضح، كان أفضل”">​</a></h2><ul><li>في Vibe Coding، فإن الأوامر التوجيهية التي تكتبها بنفس أهمية الكود الذي تكتبه. كلما كانت التعليمات أوضح وأكثر تحديدًا، كانت النتائج أقرب لما تتصوره.</li><li>توضيح الأهداف والقيود منذ البداية يُقلل من عدد التعديلات اللاحقة، مما يوفر الوقت ويقلل من استخدام الحصة والتكلفة.</li></ul><hr><h1 id="_3-نظرة-عامة-على-الأدوات-vibe-coding-أدوات-uiux" tabindex="-1">3. نظرة عامة على الأدوات (Vibe Coding / أدوات UIUX) <a class="header-anchor" href="#_3-نظرة-عامة-على-الأدوات-vibe-coding-أدوات-uiux" aria-label="Permalink to “3. نظرة عامة على الأدوات (Vibe Coding / أدوات UIUX)”">​</a></h1><h2 id="_1-منصات-ai-agent" tabindex="-1">1. منصات AI Agent <a class="header-anchor" href="#_1-منصات-ai-agent" aria-label="Permalink to “1. منصات AI Agent”">​</a></h2><table tabindex="0"><thead><tr><th><strong>الاسم</strong></th><th><strong>المنصة</strong></th></tr></thead><tbody><tr><td><strong><a href="https://lovable.dev/" target="_blank" rel="noreferrer">Lovable</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://cursor.com/cn/agents" target="_blank" rel="noreferrer">Cursor</a></strong></td><td>PC</td></tr><tr><td><strong><a href="https://chat.z.ai/" target="_blank" rel="noreferrer">Z.ai</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://replit.com/~" target="_blank" rel="noreferrer">Replit</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">Minimax</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">Trae</a></strong></td><td>PC</td></tr><tr><td><strong><a href="https://v0.app/" target="_blank" rel="noreferrer">V0</a></strong></td><td>Web-based</td></tr></tbody></table><h2 id="_2-منصات-ai-uiux" tabindex="-1">2. منصات AI UIUX <a class="header-anchor" href="#_2-منصات-ai-uiux" aria-label="Permalink to “2. منصات AI UIUX”">​</a></h2><table tabindex="0"><thead><tr><th><strong>الاسم</strong></th><th><strong>المنصة</strong></th></tr></thead><tbody><tr><td><strong><a href="https://mastergo.com/" target="_blank" rel="noreferrer">Mastergo</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://www.figma.com/" target="_blank" rel="noreferrer">Figma</a></strong></td><td>Web-based, PC Plugin</td></tr></tbody></table><hr><h1 id="_4-التطبيق-العملي-vibe-coding-تكامل-ui" tabindex="-1">4. التطبيق العملي (Vibe Coding + تكامل UI) <a class="header-anchor" href="#_4-التطبيق-العملي-vibe-coding-تكامل-ui" aria-label="Permalink to “4. التطبيق العملي (Vibe Coding + تكامل UI)”">​</a></h1><ol><li><p>في نافذة المحادثة الخاصة بمنصة Vibe Coding التي اخترتها، أدخل وصف البرنامج الذي تريده. مثال:</p><blockquote><p>يُرجى بناء تطبيق ويب بسيط للعبة الثعبان (Snake) مع واجهة أمامية وواجهة خلفية.</p><ol><li>الواجهة الأمامية</li></ol><ul><li>الصفحة 1: صفحة اللعبة <ul><li>استخدم لوحة المفاتيح للتحكم في حركة الثعبان.</li><li>ما يأكله الثعبان ليس طعامًا، بل كلمات إنجليزية.</li><li>يعرض الشريط الجانبي الكلمات المجمّعة وعددها.</li><li>بعد انتهاء اللعبة، تظل الكلمات المجمّعة محفوظة وتستمر في الجولة الجديدة.</li></ul></li><li>الصفحة 2: صفحة كتابة القصائد (Make Poem) <ul><li>تعرض نفس قائمة الكلمات الموجودة في صفحة اللعبة (البيانات متسقة).</li><li>توفر زرًا لإرسال الكلمات المجمّعة إلى الواجهة الخلفية لتوليد قصيدة.</li><li>بعد توليد القصيدة، تُزال الكلمات المُستخدَمة من القائمة أو يُنقص عددها.</li></ul></li></ul><ul><li>أضف تنقلًا بسيطًا للتبديل بين صفحتي Game و Make Poem.</li><li>تأكد من أن الكلمات المجمّعة مرئية في كلتا الصفحتين.</li></ul><ol start="2"><li>الواجهة الخلفية</li></ol><ul><li>وفر واجهة خلفية تستقبل الكلمات المجمّعة وتُرجع قصيدة.</li><li>استخدم DeepSeek API لتوليد القصائد.</li><li>خزّن مفتاح API في ملف <code>.env</code>، وتجاهل هذا الملف في <code>.gitignore</code>.</li></ul></blockquote></li><li><p>أدخل مفتاح DeepSeek API الخاص بك. (يمكنك الحصول عليه من <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">https://platform.deepseek.com/</a>)</p><ol><li>يُستخدم مفتاح API للنموذج اللغوي الكبير (LLM) لاستدعاء النموذج في مشروعك الخاص. وبما أنه معلومات حساسة، فلا يمكن نشرها، لذلك يجب كتابتها بشكل منفصل في ملف الإعدادات. <strong>لماذا نستخدم ملف <code>.env</code> ولا نرفعه إلى GitHub؟</strong></li></ol><ul><li>ملف <code>.env</code> مخصص لتخزين <strong>المفاتيح أو كلمات المرور</strong> (مثل مفتاح DeepSeek API).</li><li>إذا رُفع هذا الملف إلى GitHub، يمكن لأي شخص في العالم رؤية مفتاحك واستخدامه بشكل غير مصرح به.</li><li>لأسباب أمنية، نحتاج إلى إعلان تجاهل <code>.env</code> في ملف <code>.gitignore</code>، حتى لا يتتبعه Git.</li><li>هكذا، يمكن لمشروعك استخدام هذه المفاتيح محليًا بشكل طبيعي دون تسريبها في المستودع.</li></ul></li><li><p>بعد عرض النتيجة المُولَّدة، إذا وجدت أخطاء أو أشياء تحتاج إلى تعديل، يمكنك إدخال طلب التعديل مباشرة في نافذة المحادثة.</p></li><li><p>إذا لم تكن راضيًا عن تصميم الصفحة، يمكنك أيضًا اختيار إعادة تصميم الواجهة في Figma أو Mastergo، ثم إعادة أفكار التصميم إلى Agent.</p></li></ol><ul><li><strong>مثال</strong></li></ul><blockquote><p>يُرجى تصميم <strong>تطبيق ويب بصفحتين</strong> باسم <em>Word-Snake</em>.</p><ul><li><strong>صفحة Game:</strong></li><li>يتحرك الثعبان عبر لوحة المفاتيح.</li><li>الثعبان يأكل كلمات إنجليزية بدلاً من الطعام العادي.</li><li>يعرض الشريط الجانبي الأيمن الكلمات المجمّعة وعددها.</li><li>بعد انتهاء اللعبة، لا يُمسك مخزون الكلمات، بل يُستمر في الجولة الجديدة.</li><li><strong>صفحة Make Poem:</strong></li><li>تعرض نفس مخزون الكلمات المشترك.</li><li>يختار المستخدم بعض الكلمات وينقر على زر <strong>Generate Poem</strong>.</li><li>تُرسل هذه الكلمات إلى الواجهة الخلفية لتوليد قصيدة عبر DeepSeek API.</li><li>بعد توليد القصيدة، تُحذف أو يُنقص عدد الكلمات المُستخدَمة من المخزون.</li><li><strong>التنقل:</strong> عبر تبويب بسيط أو قائمة علوية للتبديل بين الصفحتين.</li><li><strong>الحالة المشتركة:</strong> تأكد من أن الكلمات المجمّعة تظل متزامنة ومرئية في كلتا الصفحتين.</li></ul></blockquote><ul><li><strong>نموذج للنتيجة</strong></li></ul><p><img src="'+o+'" alt=""><img src="'+l+'" alt=""></p><hr><h1 id="_5-مقارنة-منصات-ai-agent-كيفية-اختيار-أفضل-مجموعة-للمشاريع-البسيطة" tabindex="-1">5. مقارنة منصات AI Agent (كيفية اختيار أفضل مجموعة للمشاريع البسيطة) <a class="header-anchor" href="#_5-مقارنة-منصات-ai-agent-كيفية-اختيار-أفضل-مجموعة-للمشاريع-البسيطة" aria-label="Permalink to “5. مقارنة منصات AI Agent (كيفية اختيار أفضل مجموعة للمشاريع البسيطة)”">​</a></h1><p>تتمتع منصات Vibe Coding المختلفة بخصائص وسير عمل متنوعة. استخدمنا نفس متطلبات &quot;لعبة الثعبان مع DeepSeek API&quot; للاختبار العملي على منصات متعددة، وقمنا بتقييمها من منظور المبتدئين. فيما يلي ملخص.</p><h2 id="_1-معايير-المقارنة" tabindex="-1">1. معايير المقارنة <a class="header-anchor" href="#_1-معايير-المقارنة" aria-label="Permalink to “1. معايير المقارنة”">​</a></h2><ol><li><p><strong>الهدف (Goal)</strong> بناء تطبيق ويب للعبة الثعبان (Snake) متصل بـ DeepSeek API.</p></li><li><p><strong>تفاصيل اللعبة (Game Details)</strong></p><ol><li>تولّد اللعبة قصائد عبر DeepSeek LLM API.</li><li>الثعبان يأكل كلمات إنجليزية، والكلمات المجمّعة تظل محفوظة بعد انتهاء اللعبة وتُستخدم في الجولة الجديدة. يمكن جمع نفس الكلمة عدة مرات وتُحسب بشكل منفصل.</li><li>عند توليد قصيدة، تُزال الكلمات المُستخدَمة من المخزون.</li></ol></li><li><p><strong>الميزات الضرورية (Must-Haves)</strong></p><ol><li>صفحة واجهة أمامية قابلة للتشغيل، تتضمن لعبة الثعبان (تحكم بلوحة المفاتيح، عرض عبر Canvas).</li><li>آلية جمع الكلمات (تظهر الكلمات على اللوحة، وعند أكل الثعبان لكلمة، يُحدَّث الشريط الجانبي).</li><li>الحفاظ على مخزون الكلمات بين جولات اللعب المتعددة.</li><li>واجهة خلفية تستخدم DeepSeek API (إذا لم يكن لديك مفتاح API، يمكن إرجاع قصيدة تجريبية أولاً).</li><li>زر &quot;توليد قصيدة&quot;: عند النقر عليه يستدعي الواجهة الخلفية، ويعرض القصيدة، ويُحدِّث مخزون الكلمات بناءً على الاستخدام.</li><li>دعم مفتاح API عبر <code>.env</code>، وتجنب تسريب المفتاح عبر <code>.gitignore</code>.</li></ol></li><li><p><strong>ميزات إضافية (Nice-to-Haves)</strong></p><ol><li>يمكن للمستخدم اختيار الكلمات التي يريد استخدامها لتوليد القصيدة.</li><li>تجربة مستخدم مريحة (مثل شريط جانبي يعرض قائمة الكلمات بوضوح، وتخطيط منطقي لمنطقة عرض القصائد).</li><li>إضافة تعليقات في الكود للمبتدئين تشرح المنطق الأساسي.</li></ol></li></ol><h2 id="_2-مقارنة-مخرجات-البرمجة" tabindex="-1">2. مقارنة مخرجات البرمجة <a class="header-anchor" href="#_2-مقارنة-مخرجات-البرمجة" aria-label="Permalink to “2. مقارنة مخرجات البرمجة”">​</a></h2><h3 id="_1-lovable-web-based" tabindex="-1">1. Lovable (Web-based) <a class="header-anchor" href="#_1-lovable-web-based" aria-label="Permalink to “1. Lovable (Web-based)”">​</a></h3><ul><li><strong>نوع المنصة:</strong> عبر الويب</li><li><strong>الخصائص الرئيسية وسير العمل:</strong> يتميز Lovable بالتكامل والتعاون، حيث يُتمت تلقائيًا مهام التهيئة مثل الاتصال بقاعدة بيانات Supabase، مما يجعل عملية إعداد المشروع سلسة جدًا. تحتاج فقط إلى وصف متطلبات المشروع، وسيقوم Agent بربط الخدمات المختلفة وبناء الهيكل الأساسي.</li><li><strong>المستخدمون المناسبون:</strong> بالنسبة للمبتدئين الذين يجربون Vibe Coding لأول مرة، يُعد Lovable خيارًا ودودًا للغاية. فهو يُبسّط تعقيد تنسيق الخدمات المتعددة، مما يتيح لك التركيز على الأوامر التوجيهية والتكرار بدلاً من إعداد البيئة. بفضل الأتمتة العالية، يمكنك الحصول بسرعة على نموذج أولي قابل للتشغيل.</li><li><strong>عملية الأوامر التوجيهية:</strong><img src="'+n+'" alt=""></li><li><strong>نتيجة لعبة الثعبان:</strong></li></ul><p><img src="'+s+'" alt=""><img src="'+g+'" alt=""></p><ul><li><strong>السعر:</strong> مرتفع نسبيًا، ولكن إذا كان لديك بريد إلكتروني جامعي، يمكنك التحقق من هويتك كطالب للحصول على نصف السعر. <img src="'+d+'" alt=""></li></ul><h3 id="_2-cursor-ide" tabindex="-1">2. Cursor (IDE) <a class="header-anchor" href="#_2-cursor-ide" aria-label="Permalink to “2. Cursor (IDE)”">​</a></h3><ul><li><strong>نوع المنصة:</strong> تطبيق سطح مكتب (PC)</li><li><strong>الخصائص الرئيسية وسير العمل:</strong> Cursor هو IDE متكامل مع قدرات الذكاء الاصطناعي، يدعم Windows و macOS و Linux. يُدمج توليد الكود وإعادة الكتابة الذكية والبحث في قاعدة الكود مباشرة في بيئة التطوير. مقارنة بأدوات الويب، فهو أقرب إلى تجربة التطوير المحلي التقليدية. نظرًا لأنه بيئة محلية، تختلف إعدادات الكمبيوتر من جهاز لآخر، وقد تواجه أحيانًا مشاكل متعلقة بالبيئة. الميزة هي أن المشروع على جهازك المحلي، ولا حاجة لتنزيل أو إعداد بيئة تشغيل إضافية، حيث يعالج Cursor الكثير من الخطوات المرهقة نيابةً عنك.</li><li><strong>المستخدمون المناسبون:</strong> للمستخدمين الذين لديهم بالفعل بعض أساسيات البرمجة، يُعد Cursor بيئة مألوفة وقوية جدًا. ولكن للمبتدئين تمامًا، يحتاجون إلى فهم بنية المشروع وإدارة التبعيات وتنظيم الملفات بأنفسهم، مما يجعل منحنى التعلم أكثر انحدارًا. وهو أكثر ملاءمة للمطورين الذين يريدون إضافة مساعد ذكاء اصطناعي إلى سير البرمجة التقليدي.</li><li><strong>عملية الأوامر التوجيهية:</strong><img src="'+b+'" alt=""></li><li><strong>نتيجة لعبة الثعبان:</strong></li></ul><p><img src="'+p+'" alt=""><img src="'+h+'" alt=""></p><ul><li><strong>السعر:</strong><img src="'+c+'" alt=""></li></ul><h3 id="_3-z-ai-web-based" tabindex="-1">3. Z.ai (Web-based) <a class="header-anchor" href="#_3-z-ai-web-based" aria-label="Permalink to “3. Z.ai (Web-based)”">​</a></h3><ul><li><strong>نوع المنصة:</strong> عبر الويب</li><li><strong>الخصائص الرئيسية وسير العمل:</strong> طريقة استخدام Z.ai مباشرة نسبيًا، لكن هناك تحديًا واضحًا: تحتاج إلى <strong>نسخ الكود المُولَّد ولصقه يدويًا</strong>. تفتقر المنصة نفسها إلى نافذة معاينة فورية، لذا يصعب رؤية نتيجة تشغيل الكود في الوقت المناسب.</li><li><strong>المستخدمون المناسبون:</strong> تتطلب هذه المنصة أسلوبًا &quot;عمليًا&quot; في الاستخدام. غياب الأتمتة يعني أنه يجب عليك التعامل مع الكود مباشرة، وهو ما يمثل تدريبًا لمن يريد فهم مخرجات الذكاء الاصطناعي بعمق. لكن النسخ واللصق المتكرر يسبب مشاكل في الكفاءة وخطر الأخطاء. وهي أكثر ملاءمة لمن يريد رؤية &quot;الكود الخام من مخرجات الذكاء الاصطناعي&quot;، وليس لمن يسعى لتجربة بنقرة واحدة.</li><li><strong>عملية الأوامر التوجيهية:</strong><img src="'+u+'" alt=""></li><li><strong>نتيجة لعبة الثعبان:</strong></li></ul><p><img src="'+m+'" alt=""><img src="'+_+'" alt=""></p><ul><li><strong>السعر:</strong><img src="'+f+'" alt=""></li></ul><h3 id="_4-replit-web-based" tabindex="-1">4. Replit (Web-based) <a class="header-anchor" href="#_4-replit-web-based" aria-label="Permalink to “4. Replit (Web-based)”">​</a></h3><ul><li><p><strong>نوع المنصة:</strong> عبر الويب</p></li><li><p><strong>الخصائص الرئيسية وسير العمل:</strong> Replit هو بيئة تطوير ونشر شاملة عبر الإنترنت، حيث يمكنك كتابة الكود وتشغيل البرامج وإنشاء عنوان وصول عبر الإنترنت من المتصفح. قبل بدء البرمجة، يقدم خطة عمل واضحة؛ كما يوفر محررًا مرئيًا يمكنك من خلاله تعديل واجهة المستخدم مباشرة في نافذة المعاينة، ويتم تحديث الكود المصدري تلقائيًا. هذا يتيح لك التحقق في أي وقت مما إذا كانت مخرجات الذكاء الاصطناعي تتوافق مع التوقعات، ويقلل بشكل كبير من عدد التعديلات ذهابًا وإيابًا.</p><p><img src="'+k+'" alt=""></p></li><li><p><strong>المستخدمون المناسبون:</strong> Replit ودود جدًا للمبتدئين. فهو يُبسّط الحلقة الكاملة من البرمجة إلى النشر، دون الحاجة لإعداد خوادم أو خدمات استضافة إضافية بنفسك. ميزات التعاون قوية أيضًا، ومناسبة للطلاب الذين يعملون معًا في مشروع أو يطلبون مساعدة الآخرين عن بُعد لمراجعة الكود.</p></li><li><p><strong>عملية الأوامر التوجيهية:</strong> أثناء عملية البناء، لم يفهم الذكاء الاصطناعي المتطلبات بالكامل من البداية، وخضع لحوالي 3 جولات من التكرار قبل أن تصل المخرجات النهائية إلى المستوى المطلوب. <img src="'+A+'" alt=""></p></li><li><p><strong>نتيجة لعبة الثعبان:</strong></p></li></ul><p><img src="'+q+'" alt=""><img src="'+P+'" alt=""></p><ul><li><strong>السعر:</strong><img src="'+I+'" alt=""></li></ul><h3 id="_5-minimax-web-based" tabindex="-1">5. Minimax (Web-based) <a class="header-anchor" href="#_5-minimax-web-based" aria-label="Permalink to “5. Minimax (Web-based)”">​</a></h3><ul><li><strong>نوع المنصة:</strong> عبر الويب</li><li><strong>الخصائص الرئيسية وسير العمل:</strong> يستغرق Minimax وقتًا أطول عادةً في تنفيذ المهام. تشمل عمليته غالبًا: اكتشاف الذكاء الاصطناعي للأخطاء وإصلاحها تلقائيًا، لذلك قد تكون العملية بأكملها بطيئة وحتى مرهقة بعض الشيء. في هذا المشروع كمثال، يضع Agent عادةً خطة مفصلة أولاً، ثم يبني خطوة بخطوة الواجهة الخلفية وقاعدة البيانات ومنطق الواجهة الأمامية.</li><li><strong>المستخدمون المناسبون:</strong> نظرًا لأنه يُشغّل الاختبارات ويصلح الأخطاء تلقائيًا، فإن استهلاك الوقت والرموز (Tokens) كبير نسبيًا، لكن يمكنك رؤية بوضوح كيف يحدد الذكاء الاصطناعي المشاكل ويحلها، مما يجعله ذا قيمة تعليمية كبيرة.</li><li><strong>عملية الأوامر التوجيهية:</strong></li></ul><p><img src="'+x+'" alt=""><img src="'+C+'" alt=""><img src="'+v+'" alt=""><img src="'+V+'" alt=""></p><ul><li><strong>نتيجة لعبة الثعبان:</strong></li></ul><p><img src="'+W+'" alt=""><img src="'+w+'" alt=""></p><ul><li><strong>السعر:</strong> الإصدار المجاني قد لا يتمكن من إكمال المشاريع المعقدة من البداية إلى النهاية بسلاسة، لذا يُوصى بشدة بالترقية إلى الإصدار المدفوع لضمان بناء المشروع بالكامل. <img src="'+S+'" alt=""></li></ul><h3 id="_6-trae-ide" tabindex="-1">6. Trae (IDE) <a class="header-anchor" href="#_6-trae-ide" aria-label="Permalink to “6. Trae (IDE)”">​</a></h3><ul><li><strong>نوع المنصة:</strong> تطبيق سطح مكتب (PC)</li><li><strong>الخصائص الرئيسية وسير العمل:</strong> كتطبيق سطح مكتب، يتميز Trae عادةً بأداء أفضل وسرعة استجابة أعلى مقارنة بأدوات الويب. لكنه يتطلب التنزيل والتثبيت، مما يرفع قليلاً من حاجز الدخول لبعض المستخدمين. وبالمثل، نظرًا لكونه بيئة محلية، فإن اختلاف إعدادات الكمبيوتر وبيئات التبعية بين الأجهزة المختلفة يضيف قدرًا من عدم اليقين. الميزة هي أن Trae يساعدك في إنشاء المشروع وإعداد التشغيل محليًا، ويمكنك التطوير والتصحيح مباشرة على جهازك.</li><li><strong>المستخدمون المناسبون:</strong> أكثر ملاءمة للمستخدمين الذين يخططون لمشاريع Vibe Coding طويلة الأمد ويرغبون في استخدام أداة سطح مكتب مخصصة. للطلاب الذين يريدون فقط &quot;التجربة أحيانًا&quot;، قد لا يكون الخيار الأخف.</li><li><strong>عملية الأوامر التوجيهية:</strong><img src="'+D+'" alt=""></li><li><strong>نتيجة لعبة الثعبان:</strong></li></ul><p><img src="'+T+'" alt=""><img src="'+U+'" alt=""></p><ul><li><strong>السعر:</strong> السعر معقول نسبيًا، وحتى الإصدار المجاني كافٍ لإنجاز مشاريع صغيرة بجودة جيدة. <img src="'+M+'" alt=""></li></ul><h3 id="_7-v0-web-based" tabindex="-1">7. V0 (Web-based) <a class="header-anchor" href="#_7-v0-web-based" aria-label="Permalink to “7. V0 (Web-based)”">​</a></h3><ul><li><p><strong>نوع المنصة:</strong> عبر الويب</p></li><li><p><strong>الخصائص الرئيسية وسير العمل:</strong> V0 هو أداة متخصصة في توليد مكونات React UI، تقدمها Vercel. يتميز بتوليد واجهات عالية الجودة وقابلة للاستخدام في بيئة الإنتاج. لكن في الاستخدام الفعلي، قد تواجه مشاكل مثل &quot;صعوبة العثور على عرض الكود&quot; و&quot;عدم وجود توضيح واضح حول مكان تكوين مفتاح API&quot;.</p></li><li><p><strong>المستخدمون المناسبون:</strong> V0 مناسب جدًا للطلاب أو المصممين المهتمين بالواجهة الأمامية وتصميم UI/UX. لكنه ليس حلاً شاملاً متكاملاً، ولا يزال يتعين عليك استخدام منصات أخرى لتنفيذ منطق الواجهة الخلفية وتكامل API، لذلك إذا كان هدفك &quot;بناء تطبيق كامل في مكان واحد&quot;، فقد لا يكون الخيار الأول الأفضل.</p></li><li><p><strong>عملية الأوامر التوجيهية:</strong><img src="'+y+'" alt=""></p><p><img src="'+L+'" alt=""></p></li><li><p><strong>نتيجة لعبة الثعبان:</strong><img src="'+R+'" alt=""><img src="'+E+'" alt=""></p></li><li><p><strong>السعر:</strong> يمكن للمستخدمين المجانيين بناء حوالي 4-5 مشاريع بسيطة. <img src="'+G+'" alt=""></p></li></ul><h2 id="_3-ملخص-المقارنة-بين-المنصات" tabindex="-1">3. ملخص المقارنة بين المنصات <a class="header-anchor" href="#_3-ملخص-المقارنة-بين-المنصات" aria-label="Permalink to “3. ملخص المقارنة بين المنصات”">​</a></h2><table tabindex="0"><thead><tr><th><strong>المنصة</strong></th><th><strong>التقييم</strong></th><th><strong>نوع المنصة</strong></th><th><strong>ملاحظات</strong></th></tr></thead><tbody><tr><td><strong><a href="https://lovable.dev/" target="_blank" rel="noreferrer">Lovable</a></strong></td><td>ودود جدًا مع مبتدئي البرمجة بالذكاء الاصطناعي، سهل البدء وتجربة سلسة، خيار مثالي للبدء.</td><td>Web-based</td><td>يُتمت تلقائيًا الاتصال بخدمات مثل Supabase، مما يُقلل تكلفة الإعداد.</td></tr><tr><td><strong><a href="https://cursor.com/cn/agents" target="_blank" rel="noreferrer">Cursor</a></strong></td><td>مناسب للمستخدمين الذين لديهم خبرة تطوير مسبقة، يرفع الإنتاجية وجودة الكود بشكل كبير.</td><td>PC</td><td>يتطلب بعض أساسيات البرمجة، ويجب فهم بنية المشروع والتبعيات في البيئة المحلية بنفسك.</td></tr><tr><td><strong><a href="https://chat.z.ai/" target="_blank" rel="noreferrer">Z.ai</a></strong></td><td>أكثر ملاءمة للمستخدمين الذين لديهم أساسيات برمجة ويريدون دراسة تفاصيل كود مخرجات الذكاء الاصطناعي مباشرة.</td><td>Web-based</td><td>لا توجد نافذة معاينة، وفحص النتائج أكثر صعوبة؛ يتطلب لصق الكود يدويًا وإنشاء المجلدات والملفات وتشغيل الخدمة يدويًا.</td></tr><tr><td><strong><a href="https://replit.com/~" target="_blank" rel="noreferrer">Replit</a></strong></td><td>موصى به للمستخدمين الذين يريدون تحويل أفكارهم بسرعة إلى خدمة عبر الإنترنت قابلة للوصول.</td><td>Web-based</td><td>بيئة تطوير ونشر شاملة عبر الإنترنت، تدعم التعاون وتوفر محررًا مرئيًا.</td></tr><tr><td><strong><a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">Minimax</a></strong></td><td>مناسب لمن يريد رؤية العملية الكاملة للبحث عن الأخطاء وإصلاحها تلقائيًا بالذكاء الاصطناعي والتعلم منها، لكنه بطيء نسبيًا ويستهلك رموزًا كثيرة.</td><td>Web-based</td><td>العملية بأكملها طويلة، ويُشغّل الذكاء الاصطناعي الاختبارات ويصلح الأخطاء عدة مرات تلقائيًا.</td></tr><tr><td><strong><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">Trae</a></strong></td><td>للمستخدمين ذوي الخبرة في البرمجة الذين يتطلعون لاستخدام مزيج IDE سطح المكتب + AI Agent، أداة قوية لتعزيز الكفاءة.</td><td>PC</td><td>يتطلب تثبيتًا محليًا وإعداد بيئة، لكن أداءً أفضل، ومناسب لمشاريع Vibe Coding طويلة الأمد.</td></tr><tr><td><strong><a href="https://v0.app/" target="_blank" rel="noreferrer">V0</a></strong></td><td>مُحسَّن لغير المطورين الذين يريدون صنع تأثيرات مرئية سريعة لـ React UI، مناسب للطلاب ذوي التوجه الأمامي/التصميم.</td><td>Web-based</td><td>متخصص في توليد React UI، ويحتاج للتعاون مع منصات أخرى لإكمال الواجهة الخلفية وبناء التطبيق الكامل.</td></tr></tbody></table><hr><h2 id="title-comparison-of-7-ai-coding-tools-description-a-hands-on-benchmark-of-popular-web-vibe-coding-platforms-using-one-unified-task-covering-beginner-friendliness-code-control-and-deployment" tabindex="-1">title: &#39;Comparison Of 7 AI Coding Tools&#39; description: &#39;A hands-on benchmark of popular Web Vibe Coding platforms using one unified task, covering beginner-friendliness, code control, and deployment.&#39; <a class="header-anchor" href="#title-comparison-of-7-ai-coding-tools-description-a-hands-on-benchmark-of-popular-web-vibe-coding-platforms-using-one-unified-task-covering-beginner-friendliness-code-control-and-deployment" aria-label="Permalink to “title: &#39;Comparison Of 7 AI Coding Tools&#39;description: &#39;A hands-on benchmark of popular Web Vibe Coding platforms using one unified task, covering beginner-friendliness, code control, and deployment.&#39;”">​</a></h2>',97)])])}const B=r(X,[["render",Z]]);export{F as __pageData,B as default};
